#!/usr/bin/env python3
"""Auditable IPv6 lookup pipeline: compile + lookup (SCAMP-Trie-like codec)."""
import sys
import json
import math

FULL = (1 << 128) - 1
HEXCHARS = set('0123456789abcdefABCDEF')
ADDRCHARS = HEXCHARS | {':'}


class Invalid(Exception):
    pass


# ---------------- strict JSON parsing ----------------

def _const(x):
    raise Invalid()

def _float(x):
    raise Invalid()

def _hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Invalid()
        d[k] = v
    return d

def loads_strict(s):
    return json.loads(s, object_pairs_hook=_hook,
                      parse_constant=_const, parse_float=_float)


def check_depth(bs):
    depth = 0
    i = 0
    n = len(bs)
    instr = False
    while i < n:
        c = bs[i]
        if instr:
            if c == 0x5c:  # backslash
                i += 2
                continue
            if c == 0x22:
                instr = False
            i += 1
            continue
        if c == 0x22:
            instr = True
            i += 1
            continue
        if c == 0x7b or c == 0x5b:  # { [
            depth += 1
            if depth > 200:
                raise Invalid()
        elif c == 0x7d or c == 0x5d:  # } ]
...


def reduce_frac(n, d):
    if n == 0:
        return (0, 1)
    g = math.gcd(n, d)
    return (n // g, d // g)


def max_ratio(used, caps):
    bn = 0
    bd = 1
    for u, c in zip(used, caps):
        if u * bd > bn * c:
            bn = u
            bd = c
    return reduce_frac(bn, bd)


# ---------------- handlers ----------------

def handle_compile(req):
    parsed, caps, ms, S = validate_compile(req)
    costmap = build_costmap(parsed, ms)
    res = solve_cuts(costmap, caps, ms, S)
    if res is None:
        return {"status": "infeasible"}
    cuts, _ = res
    stages, used = build_stages(parsed, cuts, ms)
    for i in range(S):
        if used[i] > caps[i]:
            return {"status": "infeasible"}
    num, den = max_ratio(used, caps)
    return {
        "status": "ok",
        "capacities": caps,
        "max_stride": ms,
        "cuts": cuts,
        "stages": stages,
        "used_bits": used,
        "peak": {"num": num, "den": den},
    }


def validate_lookup_image(image):
    if not isinstance(image, dict):
        raise Invalid()
    if set(image.keys()) != {'status', 'capacities', 'max_stride', 'cuts',
                              'stages', 'used_bits', 'peak'}:
        raise Invalid()
    if image['status'] != 'ok':
        raise Invalid()
    caps = image['capacities']
    ms = image['max_stride']
    cuts = image['cuts']
    stages = image['stages']
    used = image['used_bits']
    peak = image['peak']

    if not isinstance(caps, list):
        raise Invalid()
    S = len(caps)
    if not (4 <= S <= 16):
        raise Invalid()
    for x in caps:
        if type(x) is not int or x <= 0 or x > 10 ** 9:
            raise Invalid()
    if type(ms) is not int or not (1 <= ms <= 32):
        raise Invalid()

    if not isinstance(cuts, list) or len(cuts) != S + 1:
        raise Invalid()
    for c in cuts:
        if type(c) is not int or c < 0 or c > 128:
            raise Invalid()
    if cuts[0] != 0 or cuts[S] != 128:
        raise Invalid()
    for i in range(S):
        if cuts[i + 1] <= cuts[i] or cuts[i + 1] - cuts[i] > ms:
            raise Invalid()

    if not isinstance(stages, list) or len(stages) != S:
        raise Invalid()
    fib = []
    seen = set()
    for si in range(S):
        st = stages[si]
        if not isinstance(st, dict) or set(st.keys()) != {'nodes'}:
            raise Invalid()
        nodes = st['nodes']
        if not isinstance(nodes, list):
            raise Invalid()
        b = cuts[si]
        e = cuts[si + 1]
        for nd in nodes:
            if not isinstance(nd, dict) or set(nd.keys()) != {'prefix', 'rules', 'edges'}:
                raise Invalid()
            pv, pl = parse_prefix(nd['prefix'])
            if pl != b or fmt(pv, pl) != nd['prefix']:
                raise Invalid()
            rules = nd['rules']
            edges = nd['edges']
            if not isinstance(rules, list) or not isinstance(edges, list):
                raise Invalid()
            for r in rules:
                if not isinstance(r, dict) or set(r.keys()) != {'prefix', 'hop'}:
                    raise Invalid()
                rv, rl = parse_prefix(r['prefix'])
                if fmt(rv, rl) != r['prefix']:
                    raise Invalid()
                h = r['hop']
                if type(h) is not int or h < 0 or h > 65535:
                    raise Invalid()
                key = (rv, rl)
                if key in seen:
                    raise Invalid()
                seen.add(key)
                fib.append((rv, rl, h))
            for ed in edges:
                if not isinstance(ed, dict) or set(ed.keys()) != {'prefix', 'child'}:
                    raise Invalid()
                ev, el = parse_prefix(ed['prefix'])
                if el != e or fmt(ev, el) != ed['prefix']:
                    raise Invalid()
                ch = ed['child']
                if type(ch) is not int or ch < 0:
                    raise Invalid()

    if len(fib) > 2048:
        raise Invalid()
    if not isinstance(used, list) or len(used) != S:
        raise Invalid()
    for u in used:
        if type(u) is not int or u < 0:
            raise Invalid()
    if not isinstance(peak, dict) or set(peak.keys()) != {'num', 'den'}:
        raise Invalid()
    pn = peak['num']
    pd = peak['den']
    if type(pn) is not int or type(pd) is not int:
        raise Invalid()
